import os, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

# Check simple top-bottom comparison
print("=== Top-down comparison ===")
for c in range(16):
    col_in = [demo_in[r][c] for r in range(23)]
    col_out = [demo_out[r][c] for r in range(23)]

    # Find where changes happen
    changes_in_col = []
    for r in range(23):
        if col_in[r] != col_out[r]:
            changes_in_col.append((r, col_in[r], col_out[r]))

    if changes_in_col:
        print(f"Col {c}:")
        for r, v_in, v_out in changes_in_col:
            print(f"  ({r},{c}): {v_in}->{v_out}")

# Actually, let me visualize by checking patterns of contiguous 3s
print("\n=== Contiguous run analysis ===")
for c in range(16):
    runs_in = []
    curr_val = demo_in[0][c]
    run_len = 0
    for r in range(23):
        if demo_in[r][c] != curr_val:
            if run_len > 0:
                runs_in.append((curr_val, run_len))
            curr_val = demo_in[r][c]
            run_len = 1
        else:
            run_len += 1
    if run_len > 0:
        runs_in.append((curr_val, run_len))

    runs_out = []
    curr_val = demo_out[0][c]
    run_len = 0
    for r in range(23):
        if demo_out[r][c] != curr_val:
            if run_len > 0:
                runs_out.append((curr_val, run_len))
            curr_val = demo_out[r][c]
            run_len = 1
        else:
            run_len += 1
    if run_len > 0:
        runs_out.append((curr_val, run_len))

    if runs_in != runs_out:
        print(f"Col {c}: IN={runs_in} OUT={runs_out}")
